#include <iostream>
#include <queue>

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

void levelOrder(Node* root) {
    if (root == nullptr) return;

    std::queue<Node*> q;
    q.push(root); // Start with root node

    while (!q.empty()) {
        Node* curr = q.front();
        q.pop();

        std::cout << curr->data << " ";

        // Add children to the queue
        if (curr->left != nullptr) {
            q.push(curr->left);
        }
        if (curr->right != nullptr) {
            q.push(curr->right);
        }
    }
}
